Renderer::Renderer(HWND window,const std::filesystem::path& root,const GraphicsOptions& options){try{state_=std::make_unique<State>(window,root,options);}catch(const std::exception& error){if(options.api=="dx11")throw;auto reason=std::string(error.what());auto fallback=options;fallback.api="dx11";state_=std::make_unique<State>(window,root,fallback);state_->fallback="DX12 initialization failed; using DX11: "+reason;}}
Renderer::~Renderer()=default;
void Renderer::resize(unsigned width,unsigned height){if(width!=state_->width||height!=state_->height)state_->resize(width,height);}
void Renderer::invalidateArtwork(){state_->slotSerial.fill(0);state_->coverSerial.fill(0);}
void Renderer::options(const GraphicsOptions& options){auto& s=*state_;if(options.archive!=s.options.archive)throw std::invalid_argument("Scene asset changes require releasing the previous graphics resources");bool rayChanged=options.reflections!=s.options.reflections;bool resized=rayChanged||options.reflectionQuality!=s.options.reflectionQuality||options.upscaleQuality!=s.options.upscaleQuality||options.scale!=s.options.scale||options.shadows!=s.options.shadows||options.pixelRatio!=s.options.pixelRatio||options.aoResolution!=s.options.aoResolution||options.transmission!=s.options.transmission;bool samplerChanged=options.anisotropy!=s.options.anisotropy;s.options=options;if(samplerChanged)s.anisotropy();if(rayChanged){s.context->Flush();s.wait();s.updateRays();}if(resized)s.resize(s.width,s.height);}
XMFLOAT2 Renderer::jitter()const{return state_->jitter();}unsigned Renderer::renderWidth()const{return state_->rw;}unsigned Renderer::renderHeight()const{return state_->rh;}
ID2D1DeviceContext5* Renderer::drawing()const{return state_->d2d.Get();}IDWriteFactory5* Renderer::writing()const{return state_->write.Get();}IDWriteFontCollection* Renderer::fonts()const{return state_->fontCollection.Get();}
void Renderer::render(const SceneFrame& frame,const json& albums,Images& images,const ScreenGlass& glass,double now,double dt,const std::function<void()>& ui){state_->render(frame,albums,images,glass,now,dt,ui,[this]{if(!capturePath_.empty()){auto path=std::move(capturePath_);capturePath_.clear();writeCapture(path);}});}
json Renderer::status()const{return state_->status();}
std::vector<std::pair<int,float>> Renderer::inspectionParts()const{std::vector<std::pair<int,float>> result;auto& state=*state_;if(state.options.archive){for(size_t i=state.mainGeometryCount;i<state.rayAssembly.size();++i){const auto& part=state.rayAssembly[i].part;result.push_back({int(i+1),part=="fasteners"?2.75f:part=="cover"?1.85f:part=="optical-lenses"?.75f:part=="optical-core"?-.15f:part=="substrate"?-1.1f:-2.05f});}result.push_back({state.print.mask,1.85f});}else for(size_t i=0;i<state.rayAssembly.size();++i){const auto& mesh=state.rayAssembly[i];result.push_back({int(i+1),mesh.surface=="Frosted_Polymer"||mesh.surface=="Album_Print"?.85f:mesh.surface=="Optical_Diffuser"?-.35f:-1.05f});}return result;}

